\begin{tikzpicture}[x=8mm,y=12mm]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\definecolor{curveBlue}{HTML}{268CFF}\definecolor{curveRed}{HTML}{EF6068}\definecolor{curveGreen}{HTML}{4F9B63}
\draw[<->,line width=0.5pt] (-6,0)--(6,0) node[right] {$x$};
\draw[<->,line width=0.5pt] (0,-2.3)--(0,2.3) node[above] {$y$};
\draw[dashed,line width=0.4pt] (-5,0)--(-5,1)--(5,1)--(5,-1)--(0,-1);
\foreach \x in {-5,-1,1,5}{\draw[line width=0.4pt] (\x,0.05)--(\x,-0.05) node[below] {\special{dvisvgm:raw <g data-graph-text="tick">}$\x$\special{dvisvgm:raw </g>}};}
\foreach \y in {-1,1}{\node[left] at (0,\y) {\special{dvisvgm:raw <g data-graph-text="tick">}$\y$\special{dvisvgm:raw </g>}};}
\draw[curveBlue,<->,line width=0.8pt,samples=120,domain=0.04:5.8] plot (\x,{ln(\x)/ln(5)});
\draw[curveRed,dashed,<->,line width=0.8pt,samples=120,domain=0.04:5.8] plot (\x,{-ln(\x)/ln(5)});
\draw[curveGreen,<->,line width=0.8pt,samples=120,domain=-5.8:-0.04] plot (\x,{ln(-\x)/ln(5)});
\node[anchor=west,text=curveBlue] at (-6,3.8) {$y=\log_5x$};
\node[anchor=west,text=curveRed] at (-6,3.2) {$y=\log_{\frac15}x$ (dashed)};
\node[anchor=west,text=curveGreen] at (-6,2.6) {$y=\log_5(-x)$};
\end{tikzpicture}

